// Daily IndexNow cron — LoadSaathi.
//
// Stateless incremental submitter. Every day it fetches the live sitemap and
// notifies IndexNow for URLs whose <lastmod> is within the last 72 hours
// (newly-published or materially-updated pages). The homepage is always
// included (single URL, cheap, keeps the site fresh).
//
// This intentionally avoids persistent state: the sitemap's honest lastmod
// dates (real publish/edit dates, regenerated by scripts/generate-sitemap.mjs)
// are the change signal. URLs that were not touched are never resubmitted, so
// there are no duplicate submissions from this cron.
//
// Secrets: INDEXNOW_KEY (public key — not secret), optional CRON_SECRET
// (when set, a `Bearer` header must match; Vercel cron requests normally
// carry no headers, so the cron still runs when CRON_SECRET is unset).

export const config = { runtime: 'nodejs', maxDuration: 60 };

const SITE_URL = 'https://loadsaathi.in';
const HOST = 'loadsaathi.in';
const ENDPOINT = 'https://api.indexnow.org/indexnow';
const WINDOW_MS = 72 * 60 * 60 * 1000;
const BATCH = 500;
const MAX_ATTEMPTS = 3;

const json = (res, status, body) => {
  res.statusCode = status;
  res.setHeader('Content-Type', 'application/json; charset=utf-8');
  res.setHeader('Cache-Control', 'no-store');
  res.end(JSON.stringify(body));
};

const log = (level, msg, extra = {}) => {
  console.log(JSON.stringify({ ts: new Date().toISOString(), level, component: 'indexnow-cron', msg, ...extra }));
};

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

async function fetchSitemap() {
  const res = await fetch(`${SITE_URL}/sitemap.xml`, {
    signal: AbortSignal.timeout(15000),
    headers: { 'User-Agent': 'LoadSaathiIndexNow/1.0 (+https://loadsaathi.in)' },
  });
  if (!res.ok) throw new Error(`sitemap HTTP ${res.status}`);
  return res.text();
}

/** Parse <loc>/<lastmod> pairs from the sitemap XML. */
function parseSitemap(xml) {
  const urls = [];
  const locRe = /<loc>([^<]+)<\/loc>/g;
  const lastmodRe = /<lastmod>([^<]+)<\/lastmod>/g;
  const locs = [...xml.matchAll(locRe)].map((m) => m[1]);
  const lastmods = [...xml.matchAll(lastmodRe)].map((m) => m[1]);
  if (locs.length !== lastmods.length) {
    throw new Error(`sitemap loc/lastmod mismatch (${locs.length}/${lastmods.length})`);
  }
  for (let i = 0; i < locs.length; i += 1) {
    urls.push({ loc: locs[i], lastmod: lastmods[i] });
  }
  return urls;
}

async function submitBatch(batch) {
  const payload = {
    host: HOST,
    key: process.env.INDEXNOW_KEY || '',
    keyLocation: `${SITE_URL}/${process.env.INDEXNOW_KEY || ''}.txt`,
    urlList: batch,
  };
  for (let attempt = 1; attempt <= MAX_ATTEMPTS; attempt += 1) {
    let res;
    try {
      res = await fetch(ENDPOINT, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json; charset=utf-8' },
        body: JSON.stringify(payload),
        signal: AbortSignal.timeout(15000),
      });
    } catch (err) {
      log('error', 'indexnow request failed', { attempt, error: String((err && err.message) || err) });
      if (attempt === MAX_ATTEMPTS) return { status: 0, body: 'network_error' };
      await sleep(attempt * 5000);
      continue;
    }
    const text = await res.text();
    if (res.status === 429 && attempt < MAX_ATTEMPTS) {
      await sleep(attempt * 5000);
      continue;
    }
    return { status: res.status, body: text };
  }
  return { status: 429, body: 'rate_limited' };
}

export default async function handler(req, res) {
  if (req.method !== 'GET' && req.method !== 'POST') {
    return json(res, 405, { error: 'Method not allowed' });
  }

  const secret = process.env.CRON_SECRET;
  if (secret) {
    const auth = req.headers.authorization || '';
    if (auth !== `Bearer ${secret}`) {
      return json(res, 401, { error: 'Unauthorized' });
    }
  }

  const key = process.env.INDEXNOW_KEY;
  if (!key) {
    return json(res, 503, { error: 'INDEXNOW_KEY not configured' });
  }

  let xml;
  try {
    xml = await fetchSitemap();
  } catch (err) {
    log('error', 'sitemap fetch failed', { error: String((err && err.message) || err) });
    return json(res, 502, { error: 'sitemap fetch failed', message: String((err && err.message) || err) });
  }

  let urls;
  try {
    urls = parseSitemap(xml);
  } catch (err) {
    return json(res, 502, { error: 'sitemap parse failed', message: String((err && err.message) || err) });
  }

  const cutoff = Date.now() - WINDOW_MS;
  const eligible = urls.filter((u) => {
    if (u.loc === `${SITE_URL}/`) return true; // homepage always
    const mod = Date.parse(u.lastmod);
    if (Number.isNaN(mod)) return false;
    return mod >= cutoff;
  });

  if (!eligible.length) {
    log('info', 'no eligible URLs', { total: urls.length });
    return json(res, 200, { ok: true, submitted: 0, eligible: 0, total: urls.length });
  }

  const urlList = eligible.map((u) => u.loc);
  const results = [];
  let upstreamStatus = null;
  for (let i = 0; i < urlList.length; i += BATCH) {
    const chunk = urlList.slice(i, i + BATCH);
    const r = await submitBatch(chunk);
    upstreamStatus = r.status;
    results.push({ count: chunk.length, status: r.status, body: r.body });
    if (r.status === 429) break;
  }

  const ok = results.every((r) => r.status === 200 || r.status === 202);
  log('info', 'cron done', { eligible: urlList.length, upstreamStatus, batches: results.length, ok });

  return json(res, ok ? 200 : (upstreamStatus === 429 ? 429 : 502), {
    ok,
    submitted: urlList.length,
    windowHours: 72,
    results,
    note: 'HTTP 200 from IndexNow means URLs were RECEIVED — not indexed.',
  });
}
